var CROP_MANDI_SEARCH_TERMS = {
  rice: ["Paddy(Dhan)(Common)", "Paddy", "Rice"],
  wheat: ["Wheat"],
  cotton: ["Cotton"],
  soybean: ["Soyabean", "Soybean"],
  tomato: ["Tomato"],
  sugarcane: ["Sugarcane"],
  maize: ["Maize"],
  chickpea: ["Bengal Gram(Gram)(Whole)", "Bengal Gram", "Gram"]
};
function commodityToCropId(commodity) {
  const text3 = commodity.toLowerCase().trim();
  if (!text3) return null;
  for (const [cropId, terms] of Object.entries(CROP_MANDI_SEARCH_TERMS)) {
    for (const term of terms) {
      const t2 = term.toLowerCase();
      const head = t2.split("(")[0]?.trim() ?? t2;
      if (text3.includes(head) || head.includes(text3.split("(")[0]?.trim() ?? text3)) {
        return cropId;
      }
    }
  }
  if (/paddy|dhan|\brice\b/.test(text3)) return "rice";
  if (/wheat/.test(text3)) return "wheat";
  if (/cotton/.test(text3)) return "cotton";
  if (/soy/.test(text3)) return "soybean";
  if (/tomato/.test(text3)) return "tomato";
  if (/sugarcane|ganna/.test(text3)) return "sugarcane";
  if (/maize|\bcorn\b/.test(text3)) return "maize";
  if (/gram|chickpea|bengal/.test(text3)) return "chickpea";
  return null;
}
function normalizeMandiCropId(cropId, commodity) {
  const fromCommodity = commodityToCropId(commodity);
  if (fromCommodity) return fromCommodity;
  if (cropId.startsWith("ag_")) {
    const fromSlug = commodityToCropId(cropId.replace(/^ag_/, "").replace(/_/g, " "));
    if (fromSlug) return fromSlug;
  }
  return cropId;
}

