// src/services/nearbyAgPlacesService.ts
function toNumber(value) {
  if (value == null) return 0;
  const n = typeof value === "number" ? value : Number(value);
  return Number.isFinite(n) ? n : 0;
}
function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a2 = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a2), Math.sqrt(1 - a2));
}
function matchesType(placeType, filter) {
  if (filter === "all") return true;
  if (filter === "mandi") return placeType === "mandi";
  return placeType === "fertilizer_shop" || placeType === "seed_shop" || placeType === "dealer";
}
function rowToNearby(row, fromLat, fromLon) {
  const lat = toNumber(row.latitude);
  const lon = toNumber(row.longitude);
  return {
    id: row.id,
    placeType: row.placeType,
    name: row.name,
    district: row.district,
    state: row.state,
    address: row.address,
    latitude: lat,
    longitude: lon,
    phone: row.phone,
    distanceKm: Math.round(haversineKm(fromLat, fromLon, lat, lon) * 10) / 10,
    source: "database"
  };
}
async function seedCuratedAgPlaces() {
  let inserted = 0;
  let skipped = 0;
  for (const place of CURATED_AG_PLACES) {
    const existing = await db.select({ id: agPlaces.id }).from(agPlaces).where(and(eq(agPlaces.name, place.name), eq(agPlaces.district, place.district))).limit(1);
    if (existing.length) {
      skipped++;
      continue;
    }
    await db.insert(agPlaces).values({
      placeType: place.placeType,
      name: place.name,
      district: place.district,
      state: place.state,
      address: place.address ?? null,
      latitude: String(place.latitude),
      longitude: String(place.longitude),
      phone: place.phone ?? null,
      source: "curated"
    });
    inserted++;
  }
  return { inserted, skipped };
}
async function findNearbyAgPlacesFromDb(latitude, longitude, type = "all", radiusKm = 50, limit = 20) {
  const rows = await db.select().from(agPlaces).where(eq(agPlaces.active, true));
  return rows.filter((row) => matchesType(row.placeType, type)).map((row) => rowToNearby(row, latitude, longitude)).filter((p2) => p2.distanceKm <= radiusKm).sort((a2, b2) => a2.distanceKm - b2.distanceKm).slice(0, limit);
}

